/* Local honeycomb layout. Legal labels and relationships come from the adapter. */
(function(global){'use strict';
function mount(host,graph,onSelect){
 const NS='http://www.w3.org/2000/svg',el=(tag,a={})=>{const e=document.createElementNS(NS,tag);Object.entries(a).forEach(([k,v])=>e.setAttribute(k,v));return e;};
 const bar=document.createElement('div');bar.className='hive-navigation';const back=document.createElement('button'),status=document.createElement('span'),more=document.createElement('button');back.textContent='上一步';more.textContent='下一組關聯';bar.append(back,status,more);
 const svg=el('svg',{width:'100%',height:'100%','aria-label':'蜂巢關係圖，可拖曳與縮放'}),scene=el('g');svg.append(scene);host.replaceChildren(bar,svg);
 const nodes=graph.nodes.map(n=>({...n})),by=new Map(nodes.map(n=>[n.key,n])),adj=new Map(nodes.map(n=>[n.key,new Set()]));graph.edges.forEach(([a,b])=>{if(by.has(a)&&by.has(b)){adj.get(a).add(b);adj.get(b).add(a);}});
 const colors={question:['#ffffff','#285C8E'],issue:['#ffffff','#945124'],article:['#ffffff','#286347'],pack:['#ffffff','#684E8A']};
 let selected=null,history=[],page=0,scale=1,tx=0,ty=0,moved=false,previous=null;const pointers=new Map();
 const mobile=()=>global.innerWidth<=600;let radius=mobile()?43:62;
 const point=(q,r)=>({x:radius*1.5*q,y:radius*Math.sqrt(3)*(r+q/2)});
 function ring(n){if(!n)return [[0,0]];const out=[];let q=0,r=-n;for(const [dq,dr] of [[1,0],[0,1],[-1,1],[-1,0],[0,-1],[1,-1]])for(let i=0;i<n;i++){out.push([q,r]);q+=dq;r+=dr;}return out;}
 function transform(){scene.setAttribute('transform',`translate(${host.clientWidth/2+tx} ${(host.clientHeight-(bar.hidden?0:bar.offsetHeight))/2+ty}) scale(${scale})`);}
 function label(n){const limit=graph.tutorial&&!mobile()?7:5,cut=(v,max=limit)=>{const chars=Array.from(v);return chars.length>max?chars.slice(0,max-1).join('')+'…':v;};
 if(n.kind==='article')return [n.label.replace('民法第','民§').replace('刑法第','刑§').replace('條',''),...(!selected&&!graph.tutorial?['出現 '+n.frequency+' 次']:[])];
 if(n.kind==='question'){const year=String(n.obj.year_roc||n.obj.year||n.label.match(/(\d{2,3})$/)?.[1]||'');return [year+' '+(String(n.obj.category||n.obj.subject||'').includes('物權')?'物權':String(n.obj.category||n.obj.subject||'').includes('刑法')?'刑總':'民總'),cut(n.label.replace(/\s*\d+$/,''))];}
 return n.kind==='pack'?['包：',cut(n.label)]:[Array.from(n.label).slice(0,limit).join(''),cut(Array.from(n.label).slice(limit).join(''))];}

 nodes.forEach(n=>{n.frequency=[...adj.get(n.key)].filter(k=>by.get(k).kind==='question').length;const g=el('g',{tabindex:0,role:'button','aria-label':n.label});g.dataset.key=n.key;g.dataset.kind=n.kind;n.g=g;const p=el('polygon');n.polygon=p;g.append(p);const t=el('text',{'text-anchor':'middle','font-size':13,fill:colors[n.kind][1],'font-family':'-apple-system, SF Pro Display, Helvetica Neue, PingFang TC, Noto Sans TC, sans-serif','font-weight':700});n.text=t;g.append(t);const title=el('title');title.textContent=n.label;g.append(title);g.addEventListener('click',()=>{if(!moved)select(n.key);});g.addEventListener('keydown',e=>{if(['Enter',' '].includes(e.key)){e.preventDefault();select(n.key);}});scene.append(g);});
 function layout(){radius=graph.tutorial?(mobile()?43:80):(mobile()?43:50);const positions=new Map(),levels=new Map();
 if(graph.tutorial){nodes.forEach((n,i)=>{positions.set(n.key,i?ring(1)[i-1]:[0,0]);levels.set(n.key,i?1:0);});}
 else if(selected){positions.set(selected,[0,0]);levels.set(selected,0);const direct=[...adj.get(selected)].filter(k=>by.get(selected).kind!=='article'||by.get(k).kind==='question');const first=direct.slice(page*6,page*6+6);first.forEach((k,i)=>{positions.set(k,ring(1)[i]);levels.set(k,1);});const outer=[...new Set(first.flatMap(k=>[...adj.get(k)]))].filter(k=>k!==selected&&!direct.includes(k));outer.slice(0,12).forEach((k,i)=>{positions.set(k,ring(2)[i]);levels.set(k,2);});more.hidden=direct.length<=6;more.textContent='下一組關聯（'+(page+1)+'/'+Math.ceil(direct.length/6)+'）';}
 else {const slots=[[0,0],...ring(1),...ring(2)],sorted=[...nodes].sort((a,b)=>(a.kind==='question'?0:a.kind==='article'?1:2)-(b.kind==='question'?0:b.kind==='article'?1:2)||b.frequency-a.frequency);sorted.slice(page*19,page*19+19).forEach((n,i)=>positions.set(n.key,slots[i]));more.hidden=nodes.length<=19;more.textContent='下一頁（'+(page+1)+'/'+Math.max(1,Math.ceil(nodes.length/19))+'）';}
 back.hidden=graph.tutorial||!selected;bar.hidden=!!graph.tutorial;status.textContent=selected?by.get(selected).label:'總覽只是索引，點一格看關聯';
 nodes.forEach(n=>{const slot=positions.get(n.key);n.g.style.display=slot?'':'none';n.g.dataset.level='';if(!slot)return;const p=point(...slot);n.g.dataset.x=p.x;n.g.dataset.y=p.y;n.g.dataset.level=levels.get(n.key)??'';n.g.setAttribute('transform',`translate(${p.x} ${p.y})`);const rr=radius-2;n.polygon.setAttribute('points',Array.from({length:6},(_,i)=>`${rr*Math.cos(i*Math.PI/3)},${rr*Math.sin(i*Math.PI/3)}`).join(' '));n.polygon.setAttribute('fill',colors[n.kind][0]);n.polygon.setAttribute('stroke',colors[n.kind][1]);n.polygon.setAttribute('stroke-width',levels.get(n.key)===0?2.5:1.3);n.g.querySelector('.mm-seen')?.remove();if(n.seen){const badge=el('text',{class:'mm-seen',x:0,y:-radius*.53,'text-anchor':'middle',fill:'#286347','font-size':12});badge.textContent='✓';n.g.append(badge);}n.text.replaceChildren();const lines=label(n);lines.forEach((line,i)=>{const s=el('tspan',{x:0,y:(i-(lines.length-1)/2)*17+5});s.textContent=line;n.text.append(s);});});if(graph.tutorial){const ps=[...positions.values()].map(v=>point(...v));tx=-(Math.min(...ps.map(p=>p.x))+Math.max(...ps.map(p=>p.x)))/2;ty=-(Math.min(...ps.map(p=>p.y))+Math.max(...ps.map(p=>p.y)))/2;}transform();}
 function select(key){if(!by.has(key))return;if(!graph.tutorial){if(selected!==key){history.push(selected);page=0;}selected=key;tx=ty=0;scale=1;layout();}onSelect(by.get(key));}
 function reset(){selected=null;history=[];page=0;tx=ty=0;scale=1;layout();}
 back.onclick=()=>{selected=history.pop()||null;page=0;tx=ty=0;scale=1;layout();onSelect(selected?by.get(selected):null);};more.onclick=()=>{if(!selected){page=(page+1)%Math.ceil(nodes.length/19);tx=ty=0;scale=1;layout();return;}const count=[...adj.get(selected)].filter(k=>by.get(selected).kind!=='article'||by.get(k).kind==='question').length;page=(page+1)%Math.ceil(count/6);layout();};
 function zoom(f){scale=Math.max(.8,Math.min(3,scale*f));transform();}
 const gesture=()=>{const p=[...pointers.values()];return {x:p.reduce((s,v)=>s+v.x,0)/p.length,y:p.reduce((s,v)=>s+v.y,0)/p.length,d:p.length>1?Math.hypot(p[0].x-p[1].x,p[0].y-p[1].y):0};};
 svg.addEventListener('pointerdown',e=>{if(!pointers.size)moved=false;pointers.set(e.pointerId,{x:e.clientX,y:e.clientY});previous=gesture();});svg.addEventListener('pointermove',e=>{if(!pointers.has(e.pointerId))return;pointers.set(e.pointerId,{x:e.clientX,y:e.clientY});const g=gesture(),dx=g.x-previous.x,dy=g.y-previous.y;if(Math.abs(dx)+Math.abs(dy)>2||moved){moved=true;tx+=dx;ty+=dy;if(g.d&&previous.d)zoom(g.d/previous.d);transform();}previous=g;});const release=e=>{pointers.delete(e.pointerId);previous=pointers.size?gesture():null;};svg.addEventListener('pointerup',release);svg.addEventListener('pointercancel',release);svg.addEventListener('pointerleave',release);svg.addEventListener('wheel',e=>{e.preventDefault();zoom(Math.exp(-e.deltaY*.002));},{passive:false});
 const observer=new ResizeObserver(layout);observer.observe(host);layout();return {select,reset,refresh:layout,fit:()=>{tx=ty=0;scale=1;layout();},zoom,destroy:()=>observer.disconnect()};
}global.LawMindmap={mount};})(window);
